data_t neuron(const data_t in[], const data_t w[], data_t bias, int n, bool do_relu)
{
	data_t acc = bias;

neuron_mac:
	for (int i = 0; i < n; i++) {
		acc += in[i] * w[i];
	}

	if (do_relu && acc < (data_t)0)
		acc = (data_t)0;

	return acc;
}


void mlp(const data_t input[IN_SIZE], float output[OUT_SIZE])
{
	data_t a1[L1_SIZE];
	data_t a2[L2_SIZE];
	data_t a3[L3_SIZE];
	data_t z4[OUT_SIZE];

	/* --- Layer 1 : 784 -> 5 , ReLU --- */
layer1:
	for (int j = 0; j < L1_SIZE; j++)
		a1[j] = neuron(input, W1[j], B1[j], IN_SIZE, true);

	/* --- Layer 2 : 5 -> 8 , ReLU --- */
layer2:
	for (int j = 0; j < L2_SIZE; j++)
		a2[j] = neuron(a1, W2[j], B2[j], L1_SIZE, true);

	/* --- Layer 3 : 8 -> 8 , ReLU --- */
layer3:
	for (int j = 0; j < L3_SIZE; j++)
		a3[j] = neuron(a2, W3[j], B3[j], L2_SIZE, true);

	/* --- Layer 4 : 8 -> 10 , linear --- */
layer4:
	for (int j = 0; j < OUT_SIZE; j++)
		z4[j] = neuron(a3, W4[j], B4[j], L3_SIZE, false);

	/* --- softmax in float (numerically stable) --- */
	float logits[OUT_SIZE];
	float maxv = (float)z4[0];
	for (int j = 1; j < OUT_SIZE; j++) {
		logits[j] = (float)z4[j];
		if ((float)z4[j] > maxv)
			maxv = (float)z4[j];
	}
	logits[0] = (float)z4[0];

	float sum = 0.0f;
softmax_exp:
	for (int j = 0; j < OUT_SIZE; j++) {
		float e = expf(logits[j] - maxv);
		output[j] = e;
		sum += e;
	}
softmax_norm:
	for (int j = 0; j < OUT_SIZE; j++)
		output[j] = output[j] / sum;
}
